/* Loads the approved interface rebuild, then the original offline JSZip build. */
(() => {
  const legacyTheme = document.createElement("link");
  legacyTheme.rel = "stylesheet";
  legacyTheme.href = "./theme-oriental.css?v=2026-08-05";
  document.head.appendChild(legacyTheme);

  const rebuiltUi = document.createElement("script");
  rebuiltUi.src = "./ui-rebuild.js?v=2026-08-05-r3";
  rebuiltUi.defer = true;
  document.head.appendChild(rebuiltUi);

  document.write('<script src="vendor/jszip-core.min.js"><\/script>');
})();